export type Mark = keyof typeof SOURCES;

/** Flattens SVG path data into closed rings of points. */
export function rings(d: string): P[][] {
	const tokens = d.match(/[a-zA-Z]|-?(?:\d+\.?\d*|\.\d+)(?:e-?\d+)?/g) ?? [];
	const out: P[][] = [];
	let ring: P[] = [];
	let i = 0;
	let cmd = '';
	let cur: P = [0, 0];
	let start: P = [0, 0];
	let ctrl: P | null = null;
	let qctrl: P | null = null;
	const num = () => Number(tokens[i++]);
	const flag = () => {
		const t = tokens[i]!;
		if (t.length > 1) {
			tokens[i] = t.slice(1);
			return t[0] === '1';
		}
		i++;
		return t === '1';
	};
	const close = () => {
		if (ring.length > 2) out.push(ring);
		ring = [];
	};
	const bezier = (p0: P, p1: P, p2: P, p3: P) => {
		for (let k = 1; k <= 12; k++) {
			const t = k / 12;
			const u = 1 - t;
			ring.push([
				u * u * u * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t * t * t * p3[0],
				u * u * u * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t * t * t * p3[1],
			]);
		}
	};
	const arc = (p0: P, rx: number, ry: number, phi: number, large: boolean, sweep: boolean, p1: P) => {
		if (!rx || !ry) return ring.push(p1);
		const c = Math.cos(phi);
		const s = Math.sin(phi);
		const dx = (p0[0] - p1[0]) / 2;
		const dy = (p0[1] - p1[1]) / 2;
		const x1 = c * dx + s * dy;
		const y1 = -s * dx + c * dy;
		rx = Math.abs(rx);
		ry = Math.abs(ry);
		const lam = (x1 * x1) / (rx * rx) + (y1 * y1) / (ry * ry);
		if (lam > 1) {
			rx *= Math.sqrt(lam);
			ry *= Math.sqrt(lam);
		}
		const num2 = rx * rx * ry * ry - rx * rx * y1 * y1 - ry * ry * x1 * x1;
		const k = (large === sweep ? -1 : 1) * Math.sqrt(Math.max(0, num2 / (rx * rx * y1 * y1 + ry * ry * x1 * x1)));
		const cx1 = (k * rx * y1) / ry;
		const cy1 = (-k * ry * x1) / rx;
		const cx = c * cx1 - s * cy1 + (p0[0] + p1[0]) / 2;
		const cy = s * cx1 + c * cy1 + (p0[1] + p1[1]) / 2;
		const ang = (ux: number, uy: number, vx: number, vy: number) => Math.atan2(ux * vy - uy * vx, ux * vx + uy * vy);
		const t0 = ang(1, 0, (x1 - cx1) / rx, (y1 - cy1) / ry);
		let dt = ang((x1 - cx1) / rx, (y1 - cy1) / ry, (-x1 - cx1) / rx, (-y1 - cy1) / ry);
		if (!sweep && dt > 0) dt -= 2 * Math.PI;
		if (sweep && dt < 0) dt += 2 * Math.PI;
		const steps = Math.max(4, Math.ceil(Math.abs(dt) / 0.2));
		for (let n = 1; n <= steps; n++) {
			const t = t0 + (dt * n) / steps;
			const ex = rx * Math.cos(t);
			const ey = ry * Math.sin(t);
			ring.push([c * ex - s * ey + cx, s * ex + c * ey + cy]);
		}
	};
	while (i < tokens.length) {
		if (/[a-zA-Z]/.test(tokens[i]!)) cmd = tokens[i++]!;
		const rel = cmd === cmd.toLowerCase();
		const at = (x: number, y: number): P => (rel ? [cur[0] + x, cur[1] + y] : [x, y]);
		const C = cmd.toUpperCase();
		let next: P = cur;
		let nc: P | null = null;
		let nq: P | null = null;
		if (C === 'Z') {
			close();
			cur = start;
			ctrl = qctrl = null;
			continue;
		} else if (C === 'M') {
			close();
			next = at(num(), num());
			start = next;
			ring.push(next);
			cmd = rel ? 'l' : 'L';
		} else if (C === 'L') {
			next = at(num(), num());
			ring.push(next);
		} else if (C === 'H') {
			next = [rel ? cur[0] + num() : num(), cur[1]];
			ring.push(next);
		} else if (C === 'V') {
			next = [cur[0], rel ? cur[1] + num() : num()];
			ring.push(next);
		} else if (C === 'C' || C === 'S') {
			const p1: P = C === 'C' ? at(num(), num()) : ctrl ? [2 * cur[0] - ctrl[0], 2 * cur[1] - ctrl[1]] : cur;
			const p2 = at(num(), num());
			next = at(num(), num());
			bezier(cur, p1, p2, next);
			nc = p2;
		} else if (C === 'Q' || C === 'T') {
			const q: P = C === 'Q' ? at(num(), num()) : qctrl ? [2 * cur[0] - qctrl[0], 2 * cur[1] - qctrl[1]] : cur;
			next = at(num(), num());
			bezier(cur, [cur[0] + (2 / 3) * (q[0] - cur[0]), cur[1] + (2 / 3) * (q[1] - cur[1])], [next[0] + (2 / 3) * (q[0] - next[0]), next[1] + (2 / 3) * (q[1] - next[1])], next);
			nq = q;
		} else if (C === 'A') {
			const rx = num();
			const ry = num();
			const phi = (num() * Math.PI) / 180;
			const large = flag();
			const sweep = flag();
			next = at(num(), num());
			arc(cur, rx, ry, phi, large, sweep, next);
		} else break;
		ctrl = nc;
		qctrl = nq;
		cur = next;
	}
	close();
	return out;
}

/** Hatching across several rings at once, even-odd, so holes stay open. */
function hatchRings(rs: P[][], angle: number, gap: number, seed: number): string {
	const rnd = seeded(seed);
	const c = Math.cos(angle);
	const s = Math.sin(angle);
	const rot = ([x, y]: P): P => [x * c + y * s, -x * s + y * c];
	const back = ([x, y]: P): P => [x * c - y * s, x * s + y * c];
	const rr = rs.map((r) => r.map(rot));
	const ys = rr.flat().map((p) => p[1]);
	let d = '';
	for (let y = Math.min(...ys) + gap * rnd(); y < Math.max(...ys); y += gap * (0.75 + rnd() * 0.5)) {
		const xs: number[] = [];
		for (const r of rr)
			for (let k = 0; k < r.length; k++) {
				const a = r[k]!;
				const b = r[(k + 1) % r.length]!;
				if ((a[1] <= y && b[1] > y) || (b[1] <= y && a[1] > y)) xs.push(a[0] + ((y - a[1]) / (b[1] - a[1])) * (b[0] - a[0]));
			}
		xs.sort((p, q) => p - q);
		for (let k = 0; k + 1 < xs.length; k += 2) {
			const x0 = xs[k]! + 0.6 + rnd() * 0.8;
			const x1 = xs[k + 1]! - 0.6 - rnd() * 0.8;
			if (x1 - x0 < 1.5) continue;
			const lean = (rnd() - 0.5) * 0.8;
			const a = back([x0, y - lean]);
			const b = back([x1, y + lean]);
			const m = back([(x0 + x1) / 2, y + (rnd() - 0.3) * 0.9]);
			d += `M${r1(a[0])} ${r1(a[1])}Q${r1(m[0])} ${r1(m[1])} ${r1(b[0])} ${r1(b[1])}`;
		}
	}
	return d;
}

function simplify(pts: P[], eps: number): P[] {
	if (pts.length < 3) return pts;
	const [a, b] = [pts[0]!, pts.at(-1)!];
	const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
	let far = 0;
	let at = 0;
	for (let i = 1; i < pts.length - 1; i++) {
		const p = pts[i]!;
		const dist = Math.abs((b[0] - a[0]) * (a[1] - p[1]) - (a[0] - p[0]) * (b[1] - a[1])) / len;
		if (dist > far) [far, at] = [dist, i];
	}
	return far <= eps ? [a, b] : [...simplify(pts.slice(0, at + 1), eps).slice(0, -1), ...simplify(pts.slice(at), eps)];
}

/** Rewrites closed M/L polygons with fewer, whole-unit points: the drawing only ever shows at icon size. */
function compact(d: string): string {
	return d
		.split('M')
		.filter(Boolean)
		.map((part) => {
			const pts = part
				.replace('Z', '')
				.split('L')
				.map((xy) => xy.split(' ').map(Number) as P);
			let k = 0;
			pts.forEach((p, i) => {
				if (Math.hypot(p[0] - pts[0]![0], p[1] - pts[0]![1]) > Math.hypot(pts[k]![0] - pts[0]![0], pts[k]![1] - pts[0]![1])) k = i;
			});
			const kept = [...simplify(pts.slice(0, k + 1), 0.3).slice(0, -1), ...simplify([...pts.slice(k), pts[0]!], 0.3).slice(0, -1)].map(([x, y]) => `${Math.round(x)} ${Math.round(y)}`);
			return kept.length < 3 ? '' : 'M' + kept.join('L') + 'Z';
		})
		.join('');
}

export interface Logo {
	readonly tone: string;
	readonly hatch: string;
	readonly ink: string;
}

function draw(mark: Mark, seed: number): Logo {
	const rs = rings(SOURCES[mark]).map((r) => r.map(([x, y]) => [PAD + x * SCALE, PAD + y * SCALE] as P));
	const pen = { w: 4.2, heavy: 0.5, wobble: 0.5, over: 1.2, seed };
	const ink = rs
		.map((r, k) => {
			const xs = r.map((p) => p[0]);
			const ys = r.map((p) => p[1]);
			const span = Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys));
			return outline(r, { ...pen, w: span < 6 * SCALE ? 2.4 : pen.w, seed: seed * 17 + k });
		})
		.join('');
	const rnd = seeded(seed);
	const [dx, dy] = [(rnd() - 0.5) * 1.6, (rnd() - 0.5) * 1.6];
	const tone = rs.map((r) => pathOf(r.map(([x, y]) => [x + dx, y + dy] as P), true)).join('');
	return { tone: compact(tone), hatch: hatchRings(rs, -0.8, 4.2, seed * 5 + 1), ink: compact(ink) };
}

export function drawing() {
	const marks = Object.keys(SOURCES) as Mark[];
	return { size: SIZE, logos: Object.fromEntries(marks.map((a, i) => [a, draw(a, 41 + i * 7)])) as Record<Mark, Logo> };
}
